import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"23、【剥】 坤下艮上","description":"横渠易说 - 23、【剥】 坤下艮上","frontmatter":{"title":"23、【剥】 坤下艮上","description":"横渠易说 - 23、【剥】 坤下艮上"},"headers":[],"relativePath":"zh/classics/hengqu/025.md","filePath":"zh/classics/hengqu/025.md"}'),l={name:"zh/classics/hengqu/025.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_23、【剥】-坤下艮上" tabindex="-1">23、【剥】 坤下艮上 <a class="header-anchor" href="#_23、【剥】-坤下艮上" aria-label="Permalink to “23、【剥】 坤下艮上”">​</a></h1><h3 id="彖曰-剥-剥也-柔变刚也。-不利有攸往-小人长也。顺而止之-观象也。君子尚消息盈虚-天行也。" tabindex="-1">彖曰，剥，剥也，柔变刚也。“不利有攸往”，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也。 <a class="header-anchor" href="#彖曰-剥-剥也-柔变刚也。-不利有攸往-小人长也。顺而止之-观象也。君子尚消息盈虚-天行也。" aria-label="Permalink to “彖曰，剥，剥也，柔变刚也。“不利有攸往”，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也。”">​</a></h3><h3 id="象曰-山附于地-剥-上以厚下安宅。" tabindex="-1">象曰：山附于地，剥，上以厚下安宅。 <a class="header-anchor" href="#象曰-山附于地-剥-上以厚下安宅。" aria-label="Permalink to “象曰：山附于地，剥，上以厚下安宅。”">​</a></h3><p>处剥之时，顺上以观天理之消息盈虚。</p><h3 id="初六-剥床以足-蔑贞凶。-象曰-剥床以足-以灭下也。" tabindex="-1">初六，剥床以足，蔑贞凶。 象曰：“剥床以足”，以灭下也。 <a class="header-anchor" href="#初六-剥床以足-蔑贞凶。-象曰-剥床以足-以灭下也。" aria-label="Permalink to “初六，剥床以足，蔑贞凶。 象曰：“剥床以足”，以灭下也。”">​</a></h3><h3 id="六二-剥床以辨-蔑贞凶。-象曰-剥床以辨-未有与也。" tabindex="-1">六二，剥床以辨，蔑贞凶。 象曰：“剥床以辨”，未有与也。 <a class="header-anchor" href="#六二-剥床以辨-蔑贞凶。-象曰-剥床以辨-未有与也。" aria-label="Permalink to “六二，剥床以辨，蔑贞凶。 象曰：“剥床以辨”，未有与也。”">​</a></h3><p>三虽阴类，然志应在上，二不能进剥阳爻，徒用口舌间说，力未能胜，故象曰“未有与也”。然志在灭阳，故亦云“蔑贞凶”。</p><h3 id="六三-剥之-无咎。-象曰-剥之无咎-失上下也。" tabindex="-1">六三，剥之，无咎。 象曰：“剥之无咎”，失上下也。 <a class="header-anchor" href="#六三-剥之-无咎。-象曰-剥之无咎-失上下也。" aria-label="Permalink to “六三，剥之，无咎。 象曰：“剥之无咎”，失上下也。”">​</a></h3><p>独应于阳，故反为众阴所剥，然无所咎。</p><h3 id="六四-剥床以肤-凶。-象曰-剥床以肤-切近灾也。" tabindex="-1">六四，剥床以肤，凶。 象曰：“剥床以肤”，切近灾也。 <a class="header-anchor" href="#六四-剥床以肤-凶。-象曰-剥床以肤-切近灾也。" aria-label="Permalink to “六四，剥床以肤，凶。 象曰：“剥床以肤”，切近灾也。”">​</a></h3><p>迫近君位，犹自下剥床，至床之肤，将及于人也。不言“蔑贞”，剥道成矣。一云：五于阴阳之际，义必上比，故以喻肤。</p><h3 id="六五-贯鱼以宫人宠-无不利。-象曰-以宫人宠-终无尤也。" tabindex="-1">六五，贯鱼以宫人宠，无不利。 象曰：“以宫人宠”，终无尤也。 <a class="header-anchor" href="#六五-贯鱼以宫人宠-无不利。-象曰-以宫人宠-终无尤也。" aria-label="Permalink to “六五，贯鱼以宫人宠，无不利。 象曰：“以宫人宠”，终无尤也。”">​</a></h3><p>六五为上九之肤，能下宠众阴，则阳获安而无不利矣。异于六三者，以其居尊制裁，为卦之主，故不云“剥之”也。终无尤怨者，以小人之心不过图宠利而已，不以宫人见畜为耻也。阴阳之际，近必相比，六五能上附于阳，反制群阴不使进逼，方得处剥之善，下无剥之之忧，上得阳功之庇，故曰“无不利”。</p><h3 id="上九-硕果不食-君子得舆-小人剥庐。-象曰-君子得舆-民所载也。-小人剥庐-终不可用也。" tabindex="-1">上九，硕果不食，君子得舆，小人剥庐。 象曰：“君子得舆”，民所载也。“小人剥庐”，终不可用也。 <a class="header-anchor" href="#上九-硕果不食-君子得舆-小人剥庐。-象曰-君子得舆-民所载也。-小人剥庐-终不可用也。" aria-label="Permalink to “上九，硕果不食，君子得舆，小人剥庐。 象曰：“君子得舆”，民所载也。“小人剥庐”，终不可用也。”">​</a></h3><p>处剥之世，有美实而不见采，然其德备，犹为民所载。小人处下则剥床，处上则反伤于下，是终不可用之也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
